instance.invitation-mail:
invitation -> applicationName -> link -> {
  emailBody = #"tl.security.selfservice.mail.invitation.body".fill($applicationName, $link).localize();
  subject = #"tl.security.selfservice.mail.invitation.subject".fill($applicationName).localize();
  emailAddr = $invitation.get(`tl.security.selfservice:Invitation#email`);

  try(
    sendMail(
      subject: $subject,
      to: $emailAddr,
      body: binary(name: "mail.html", contentType: "text/html", encoding: "utf-8", data: $emailBody)
    ),
    catch: mailError -> {
      info("Sending mail to " + $emailAddr + " failed. reason: " + $mailError);
      false
    }
  );
}

